fn findToolBoundary(messages: []const Message, start_idx: usize) usize {
    var idx = start_idx;
    while (idx < messages.len) {
        const m = &messages[idx];
        if (mem.eql(u8, m.role, "tool")) {
            idx += 1;
            continue;
        }
        if (mem.eql(u8, m.role, "assistant") and m.tool_calls != null and idx + 1 < messages.len) {
            var j = idx + 1;
            while (j < messages.len and mem.eql(u8, messages[j].role, "tool")) {
                j += 1;
            }
            if (j > idx + 1) {
                idx = j;
                continue;
            }
        }
        break;
    }
    return idx;
}

fn findTurnBoundary(messages: []const Message, min_idx: usize) usize {
    var idx = findToolBoundary(messages, min_idx);
    while (idx < messages.len and !mem.eql(u8, messages[idx].role, "user")) {
        idx += 1;
    }
    if (idx >= messages.len and messages.len > 0) {
        const alt = @min(min_idx, messages.len);
        idx = findToolBoundary(messages, alt);
    }
    return @min(idx, messages.len);
}

fn stripOrphanedAssistantToolCalls(allocator: Allocator, messages: ArrayList(Message)) !void {
    if (messages.items.len == 0) return;
    var tool_ids = StringHashMap(bool).init(allocator);
    defer tool_ids.deinit();
    for (messages.items) |m| {
        if (mem.eql(u8, m.role, "tool")) {
            if (m.tool_call_id) |tid| {
                try tool_ids.put(tid, true);
            }
        }
    }
    var cleaned = ArrayList(Message).init(allocator);
    for (messages.items) |m| {
        if (mem.eql(u8, m.role, "assistant") and m.tool_calls != null) {
            var remaining = ArrayList(ToolCall).init(allocator);
            for (m.tool_calls.?.items) |tc| {
                if (tool_ids.contains(tc.id)) {
                    try remaining.append(tc);
                }
            }
            if (remaining.items.len > 0) {
                var new_msg = m.;
                new_msg.tool_calls = remaining;
                try cleaned.append(new_msg);
            } else if (m.content_str != null and m.content_str.?.len > 0) {
                var new_msg = Message{
                    .role = try allocator.dupe(u8, "assistant"),
                    .content_str = try allocator.dupe(u8, m.content_str.?),
                    .content_parts = null,
                    .tool_calls = null,
                    .tool_call_id = null,
                    .allocator = allocator,
                };
                try cleaned.append(new_msg);
                remaining.deinit();
            } else {
                remaining.deinit();
            }
        } else {
            try cleaned.append(m.);
        }
    }
    messages.clearRetainingCapacity();
    for (cleaned.items) |m| {
        try messages.append(m);
    }
    cleaned.deinit();
}

fn trimHistory(allocator: Allocator, history: ArrayList(Message)) !void {
    if (history.items.len <= MAX_STORED_MESSAGES) return;
    const cut_target = history.items.len  MAX_STORED_MESSAGES;
    var cut = findTurnBoundary(history.items, cut_target);
    if (cut >= history.items.len) {
        cut = if (history.items.len > MAX_STORED_MESSAGES) history.items.len  MAX_STORED_MESSAGES else 0;
    }
    if (cut > 0) {
        var i: usize = 0;
        while (i < cut and history.items.len > 0) : (i += 1) {
            var m = history.orderedRemove(0);
            m.deinit();
        }
    }
    try stripOrphanedAssistantToolCalls(allocator, history);
}

