fn urlPercentEncode(allocator: Allocator, input: []const u8) ![]u8 {
    var out = ArrayList(u8).init(allocator);
    for (input) |c| {
        if ((c >= 'A' and c <= 'Z') or (c >= 'a' and c <= 'z') or (c >= '0' and c <= '9') or c == '' or c == '_' or c == '.' or c == '~') {
            try out.append(c);
        } else {
            try out.writer().print("%{X:0>2}", .{c});
        }
    }
    return out.toOwnedSlice();
}

fn buildDbUrl(allocator: Allocator) ![]u8 {
    const username = getEnv(allocator, "DB_USERNAME", DB_USERNAME_DEFAULT);
    const password = getEnv(allocator, "DB_PASSWORD", "");
    const host = getEnv(allocator, "DB_HOST", DB_HOST_DEFAULT);
    const port = getEnv(allocator, "DB_PORT", DB_PORT_DEFAULT);
    const database = getEnv(allocator, "DB_DATABASE", DB_DATABASE_DEFAULT);
    const enc_user = try urlPercentEncode(allocator, username);
    defer allocator.free(enc_user);
    const enc_pass = try urlPercentEncode(allocator, password);
    defer allocator.free(enc_pass);
    return fmt.allocPrint(allocator, "postgresql://{s}:{s}@{s}:{s}/{s}", .{ enc_user, enc_pass, host, port, database });
}

fn normalizeExaQueries(allocator: Allocator, queries: []const []const u8) !ArrayList([]u8) {
    var valid = ArrayList([]u8).init(allocator);
    var seen = StringHashMap(bool).init(allocator);
    defer seen.deinit();
    for (queries) |q| {
        const stripped = mem.trim(u8, q, " \t\n\r");
        if (stripped.len == 0) continue;
        var lower_buf = try allocator.alloc(u8, stripped.len);
        defer allocator.free(lower_buf);
        for (stripped, 0..) |c, i| {
            lower_buf[i] = std.ascii.toLower(c);
        }
        if (seen.contains(lower_buf)) continue;
        try seen.put(try allocator.dupe(u8, lower_buf), true);
        try valid.append(try allocator.dupe(u8, stripped));
    }
    return valid;
}

fn extractImageKeysFromMessages(allocator: Allocator, msgs: []const Message) !ArrayList([]u8) {
    var keys = ArrayList([]u8).init(allocator);
    for (msgs) |m| {
        if (m.content_parts) |parts| {
            for (parts.items) |part| {
                switch (part) {
                    .image_ref => |ir| {
                        if (ir.key.len > 0) try keys.append(try allocator.dupe(u8, ir.key));
                    },
                    else => {},
                }
            }
        }
        if (mem.eql(u8, m.role, "tool")) {
            if (m.content_str) |cs| {
                if (mem.indexOf(u8, cs, "\"type\":\"image_generation\"")) |_| {
                    if (mem.indexOf(u8, cs, "\"image_key\":\"")) |key_start| {
                        const after = cs[key_start + 13 ..];
                        if (mem.indexOf(u8, after, "\"")) |key_end| {
                            const key = after[0..key_end];
                            if (key.len > 0) try keys.append(try allocator.dupe(u8, key));
                        }
                    }
                }
                if (mem.indexOf(u8, cs, "Image key:")) |ik_start| {
                    const after = cs[ik_start + 10 ..];
                    const stripped = mem.trim(u8, after, " \t\n\r");
                    if (stripped.len > 0) try keys.append(try allocator.dupe(u8, stripped));
                }
            }
        }
    }
    return keys;
}

fn fallbackImagePartForDb(allocator: Allocator, stripped_b64: []const u8, img_bytes: []const u8, media_type: []const u8) !MessagePart {
    const fmt_info = detectImageFormat(img_bytes);
    const actual_mime = if (isAllowedMime(fmt_info.mime)) fmt_info.mime else media_type;
    if (img_bytes.len <= MAX_DB_INLINE_IMAGE_BYTES) {
        return MessagePart{ .image_inline = .{
            .data = try allocator.dupe(u8, stripped_b64),
            .media_type = try allocator.dupe(u8, actual_mime),
        } };
    }
    return MessagePart{ .text = .{ .text = try allocator.dupe(u8, "[image omitted from persisted session]") } };
}

fn encodeToolContent(allocator: Allocator, payload_json: []const u8) ![]u8 {
    return allocator.dupe(u8, payload_json);
}

fn sanitizeToolContentForApi(allocator: Allocator, content: []const u8) ![]u8 {
    const stripped = mem.trim(u8, content, " \t\n\r");
    if (stripped.len == 0 or stripped[0] != '{') return allocator.dupe(u8, content);
    if (mem.indexOf(u8, stripped, "\"type\":\"image_generation\"")) |_| {
        if (mem.indexOf(u8, stripped, "\"image_key\"") != null and mem.indexOf(u8, stripped, "\"image_data\"") != null) {
            var out = ArrayList(u8).init(allocator);
            var i: usize = 0;
            var skip = false;
            while (i < stripped.len) {
                if (!skip and mem.startsWith(u8, stripped[i..], "\"image_data\"")) {
                    skip = true;
                    var depth: usize = 0;
                    var found_colon = false;
                    while (i < stripped.len) {
                        if (!found_colon and stripped[i] == ':') {
                            found_colon = true;
                            i += 1;
                            continue;
                        }
                        if (found_colon) {
                            if (stripped[i] == '"') {
                                i += 1;
                                while (i < stripped.len and stripped[i] != '"') {
                                    if (stripped[i] == '\\') i += 1;
                                    i += 1;
                                }
                                i += 1;
                                break;
                            } else if (stripped[i] == '{' or stripped[i] == '[') {
                                depth += 1;
                                i += 1;
                            } else if (stripped[i] == '}' or stripped[i] == ']') {
                                if (depth == 0) break;
                                depth = 1;
                                i += 1;
                                if (depth == 0) break;
                            } else {
                                i += 1;
                            }
                        } else {
                            i += 1;
                        }
                    }
                    if (i < stripped.len and stripped[i] == ',') i += 1;
                    skip = false;
                    continue;
                }
                try out.append(stripped[i]);
                i += 1;
            }
            return out.toOwnedSlice();
        }
    }
    return allocator.dupe(u8, content);
}

const TcpConn = struct {
    stream: net.Stream,
    allocator: Allocator,

    fn deinit(self: TcpConn) void {
        self.stream.close();
    }

    fn write(self: TcpConn, data: []const u8) !void {
        try self.stream.writeAll(data);
    }

    fn read(self: TcpConn, buf: []u8) !usize {
        return self.stream.read(buf);
    }
};

fn httpPost(allocator: Allocator, url: []const u8, headers: []const struct { key: []const u8, value: []const u8 }, body: []const u8) !struct { status: u16, body: []u8 } {
    var uri = try std.Uri.parse(url);
    _ = uri;
    const host = blk: {
        const parsed = try std.Uri.parse(url);
        break :blk parsed.host orelse return error.NoHost;
    };
    const port: u16 = blk: {
        const parsed = try std.Uri.parse(url);
        if (parsed.port) |p| break :blk p;
        if (mem.startsWith(u8, url, "")) break :blk 443;
        break :blk 80;
    };
    const path = blk: {
        const parsed = try std.Uri.parse(url);
        if (parsed.path.len > 0) break :blk parsed.path else break :blk "/";
    };
    var client = http.Client{ .allocator = allocator };
    defer client.deinit();
    const uri_full = try std.Uri.parse(url);
    var req_buf: [8192]u8 = undefined;
    var req = try client.open(.POST, uri_full, .{
        .server_header_buffer = &req_buf,
    });
    defer req.deinit();
    req.transfer_encoding = .{ .content_length = body.len };
    for (headers) |h| {
        try req.headers.append(h.key, h.value);
    }
    _ = host;
    _ = port;
    _ = path;
    try req.send();
    try req.writeAll(body);
    try req.finish();
    try req.wait();
    const status = @intFromEnum(req.response.status);
    var resp_body = ArrayList(u8).init(allocator);
    try req.reader().readAllArrayList(&resp_body, 10  1024  1024);
    return .{ .status = @intCast(status), .body = try resp_body.toOwnedSlice() };
}

fn httpGet(allocator: Allocator, url: []const u8, headers: []const struct { key: []const u8, value: []const u8 }) !struct { status: u16, body: []u8 } {
    var client = http.Client{ .allocator = allocator };
    defer client.deinit();
    const uri_full = try std.Uri.parse(url);
    var req_buf: [8192]u8 = undefined;
    var req = try client.open(.GET, uri_full, .{
