    defer req.deinit();
    for (headers) |h| {
        try req.headers.append(h.key, h.value);
    }
    try req.send();
    try req.finish();
    try req.wait();
    const status = @intFromEnum(req.response.status);
    var resp_body = ArrayList(u8).init(allocator);
    try req.reader().readAllArrayList(&resp_body, 10  1024  1024);
    return .{ .status = @intCast(status), .body = try resp_body.toOwnedSlice() };
}

